CREATE TABLE sources (key TEXT PRIMARY KEY, ticker TEXT NOT NULL, exchange TEXT NOT NULL DEFAULT '', doc TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', UNIQUE(ticker, exchange));
CREATE TABLE people (id TEXT PRIMARY KEY, display_name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'UTC', token_sha256 TEXT, notify TEXT NOT NULL DEFAULT '{}', downloads_dir TEXT, notify_seq INTEGER NOT NULL DEFAULT 0);
CREATE TABLE follows (id INTEGER PRIMARY KEY, person TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, source_key TEXT REFERENCES sources(key), ticker TEXT NOT NULL, exchange TEXT NOT NULL DEFAULT '', origin TEXT NOT NULL, state TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', hints TEXT NOT NULL DEFAULT '{}', added_at TEXT NOT NULL, UNIQUE(person,ticker,exchange,origin));
CREATE TABLE registration_quotas (person TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, day TEXT NOT NULL, used INTEGER NOT NULL, PRIMARY KEY(person,day));
CREATE TABLE events (id TEXT PRIMARY KEY, source_key TEXT NOT NULL REFERENCES sources(key), date TEXT NOT NULL, rev INTEGER NOT NULL, fingerprint TEXT NOT NULL, doc TEXT NOT NULL);
CREATE INDEX events_date ON events(date);
CREATE INDEX events_source ON events(source_key);
CREATE TABLE event_revisions (seq INTEGER PRIMARY KEY AUTOINCREMENT, event_id TEXT NOT NULL, rev INTEGER NOT NULL, change TEXT NOT NULL, doc TEXT NOT NULL, run_id TEXT NOT NULL, at TEXT NOT NULL);
CREATE INDEX event_revisions_event ON event_revisions(event_id,rev);
CREATE TABLE release_watch (event_id TEXT PRIMARY KEY REFERENCES events(id) ON DELETE CASCADE, doc TEXT NOT NULL);
CREATE TABLE documents (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id) ON DELETE CASCADE, url TEXT NOT NULL, sha256 TEXT NOT NULL DEFAULT '', doc TEXT NOT NULL, UNIQUE(event_id,url,sha256));
CREATE TABLE blobs (sha256 TEXT PRIMARY KEY, size INTEGER NOT NULL, path TEXT NOT NULL, first_seen TEXT NOT NULL, last_used TEXT NOT NULL);
CREATE TABLE runs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, started TEXT NOT NULL, ended TEXT, exit INTEGER, doc TEXT NOT NULL);
CREATE TABLE fetch_state (key TEXT PRIMARY KEY, doc TEXT NOT NULL);
CREATE TABLE heal_state (key TEXT PRIMARY KEY, doc TEXT NOT NULL);
CREATE TABLE overrides (event_id TEXT NOT NULL, kind TEXT NOT NULL, doc TEXT NOT NULL, PRIMARY KEY(event_id,kind));
CREATE TABLE calendar_versions (person TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, sink TEXT NOT NULL, rev INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(person,sink));
CREATE TABLE calendar_ledger (person TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, sink TEXT NOT NULL, key TEXT NOT NULL, fingerprint TEXT NOT NULL, provider_id TEXT NOT NULL, written_at TEXT NOT NULL, PRIMARY KEY(person,sink,key));
CREATE TABLE calendar_acks (person TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, handle_sha256 TEXT NOT NULL, doc TEXT NOT NULL, PRIMARY KEY(person,handle_sha256));
CREATE TABLE deliveries (person TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, key TEXT NOT NULL, kind TEXT NOT NULL, state TEXT NOT NULL, payload TEXT NOT NULL, message_id TEXT, attempts INTEGER NOT NULL DEFAULT 0, next_attempt TEXT, sent_at TEXT, PRIMARY KEY(person,key));
CREATE TABLE document_downloads (person TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, document_id TEXT NOT NULL, path TEXT NOT NULL, sha256 TEXT NOT NULL, at TEXT NOT NULL, PRIMARY KEY(person,document_id));
CREATE TABLE profiles (person TEXT PRIMARY KEY REFERENCES people(id) ON DELETE CASCADE, label TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 0, settings TEXT NOT NULL DEFAULT '{"results":true,"brief":false,"urgent":false,"hour":8}', feed_nonce TEXT NOT NULL DEFAULT '', feed_sha256 TEXT UNIQUE, seen_seq INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE mutes (person TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE, ticker TEXT NOT NULL, exchange TEXT NOT NULL DEFAULT '', PRIMARY KEY(person,ticker,exchange));
CREATE TABLE metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
PRAGMA user_version=3;
